from pathlib import Path
import json,html,shutil,sys,math
import numpy as np
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(Path(__file__).parent))
from requests import requests
from depth_view import depth_svg,depth_html
OUT=ROOT/'deliverables/current/review'
FONT='/System/Library/Fonts/Supplemental/Arial.ttf'

def manual_steps():
    return [
      dict(title='Record the current installation',view='overview',person='Homeowner + installer',prerequisite='Existing access is safe; no pressure parts disturbed. User reported no changes since capture on 2026-10-14.',tools='Camera, ruler, labels; measurement worksheet.',action='Take the requested dimensional readings and label the matching locations. Report any future plumbing, stud or wall change before using the model for fit.',check='Readings reference the worksheet revision; any newly changed areas are identified.',stop='If a valve moves or repairs hide a cut, the old scan cannot certify current fit.'),
      dict(title='Check plumbing and factory adjustment',view='section_studs',person='Qualified plumber',prerequisite='Exact Kohler models recorded; applicable revision checked.',tools='Applicable Kohler guides, straightedge, depth gauge and correct hand tools.',action='Trace reported rear stud contact with wood; verify valve rough-in depth and identify the stem adapters separately. Check available adjustment, final seating and supply/valve leakage before selecting a repair.',check='Stud rear travel and engagement, Check 10 tip identity/depths, plaster-guard or axis-datum check, and correct adapter/handle seating recorded.',stop='Do not shorten studs, force trim, or loosen pressure-containing parts for a homeowner measurement. No valve relocation target is approved.'),
      dict(title='Resolve the support and water barrier',view='gasket',person='Qualified tile/waterproofing installer',prerequisite='Safe access through the existing opening; stone protected.',tools='Light, inspection mirror, straightedge; approved inspection method.',action='Identify sound substrate, possible backing access and the existing waterproofing system. Design supported local rebuilding or a retained plate detail from this evidence.',check='Complete gasket landing, backing/load path and compatible water-barrier connection are documented.',stop='No filler bridging the unsupported opening. Surface sealant or grout cannot establish an unseen membrane connection. No tile cutting is authorized.'),
      dict(title='Dry fit the reviewed revision',view='exploded',person='Installer with homeowner review',prerequisite='Measurements accepted; repair option and trial geometry revised.',tools='Calibrated 1:1 paper template, thickness-accurate trial part or spacers, straightedge, original hardware.',action='Check the planar template first, then trial the actual layer thickness with the original inner plate, gasket, trim and handles.',check='Worst cuts concealed with sound overlap; no rocking; continuous foam support; trim seats; threads engage; drain down; full travel and tool/removal access.',stop='Paper proves no depth clearance. Prototype materials are not approved permanent wet-area materials. Record failures; do not force the fit.'),
      dict(title='Install only the released material detail',view='section_controls',person='Installer / fabricator as assigned',prerequisite='Selected design, material data, physical fit and explicit fabrication approval complete.',tools='Approved drawing, inspected finished part and named materials from the released schedule.',action='Protect service parts, prepare the verified substrates, place supported repairs and sealing layers in the approved order, and assemble the original Kohler components.',check='Incoming dimensions, flatness, thickness, edges and finish accepted; sealing path continuous; service parts remain removable; drain unobstructed.',stop='The current seated-cover trial has solid intersections and is rejected. No selected mortar, backing, sealant, finish or cure schedule exists. Do not install from this draft.'),
      dict(title='Cure, test and preserve access',view='coverage',person='Installer; homeowner observes results',prerequisite='Selected product-specific cure and water-exposure requirements met.',tools='Approved test procedure, dry indicators and accessible inspection points.',action='First check supply/valve behavior with surfaces kept dry; then test controlled water exposure around the assembled trim while observing available access.',check='Record product cure conditions, test duration/conditions, observed locations and results. Retain a future removal procedure.',stop='Stop if moisture appears. Investigate supply leakage separately from surface-water entry. A local pass does not certify the concealed shower system.')]

def annotations(d):
    views=OUT/'views';views.mkdir(parents=True,exist_ok=True)
    shutil.copy2(ROOT/'data/evidence/user/inner-plate-front-caliper-2026-10-14.png',views/'inner_photo.png')
    shutil.copy2(ROOT/'data/evidence/user/outer-plate-front-caliper-2026-10-14.png',views/'outer_photo.png')
    font=ImageFont.truetype(FONT,27);small=ImageFont.truetype(FONT,21)
    def canvas(source):
        im=Image.open(views/(source+'.png')).convert('RGB');return im,ImageDraw.Draw(im)
    def label(draw,xy,text,color='#174e61'):
        bounds=draw.textbbox(xy,text,font=font);draw.rounded_rectangle((bounds[0]-7,bounds[1]-5,bounds[2]+7,bounds[3]+5),5,fill='white',outline=color,width=2);draw.text(xy,text,font=font,fill=color)
    def arrow(draw,p,q,color='#174e61',text=None):
        draw.line([p,q],fill=color,width=4)
        for v,w in [(p,q),(q,p)]:
            dx,dy=w[0]-v[0],w[1]-v[1];l=max(1,math.hypot(dx,dy));ux,uy=dx/l,dy/l
            draw.polygon([v,(v[0]+ux*14-uy*6,v[1]+uy*14+ux*6),(v[0]+ux*14+uy*6,v[1]+uy*14-ux*6)],fill=color)
        if text:label(draw,((p[0]+q[0])/2+8,(p[1]+q[1])/2+8),text,color)
    projections=json.loads((OUT/'view_geometry.json').read_text())
    def projected(view,point):
        v=projections[view];x,y,z=point;q=np.array(v['world_to_camera'])@np.array([x/1000,-z/1000,y/1000,1]);span=v['ortho_scale_m']
        return ((.5+q[0]/span)*v['resolution'][0],(.5-q[1]/span)*v['resolution'][1])
    def contact(draw,p,text,at):
        draw.line([p,at],fill='#126b82',width=3);draw.ellipse((p[0]-6,p[1]-6,p[0]+6,p[1]+6),fill='#ffe345',outline='#174e61',width=2);label(draw,at,text)
    cx,cy=d['trim_center_mm'];size=1300
    def pix(x,y,span=300,center=(cx,cy)):return ((x-center[0])/span*size+size/2,(center[1]-y)/span*size+size/2)
    im,dr=canvas('coverage')
    top=d['controls_mm'][1];low=d['controls_mm'][0]
    for x,y,text in [(top[0],top[1]+7,'A'),(top[0],top[1]-7,'B'),(low[0],low[1]+7,'C'),(low[0],low[1]-7,'D')]:
        p=pix(x,y);dr.ellipse((p[0]-5,p[1]-5,p[0]+5,p[1]+5),fill='#f1ce3c');label(dr,(p[0]+18,p[1]-14),text)
    arrow(dr,pix(-15,top[1]+7),pix(-15,low[1]-7),text='O')
    arrow(dr,pix(18,top[1]-7),pix(18,low[1]+7),text='I')
    byid={f['id']:f for f in d['features'] if 'contour_mm' in f}
    P=min(byid['CUT-01']['contour_mm'],key=lambda p:p[0]);Q=max(byid['CUT-03']['contour_mm'],key=lambda p:p[0]);U=max(byid['CUT-01']['contour_mm'],key=lambda p:p[1]);V=min(byid['CUT-06']['contour_mm'],key=lambda p:p[1])
    for p,text in [(P,'P'),(Q,'Q'),(U,'U'),(V,'V')]:label(dr,pix(*p),text,'#a43f22')
    label(dr,(45,35),'M01: tips A-D / M08: damage P-Q, U-V');im.save(views/'wall_measure.png')
    im,dr=canvas('inner_front');a=d['assumptions'];p=lambda x,y:pix(x,y,210,(0,40));ix,iy=d['inner_center_mm']
    xl=ix-a['inner_width_mm']/2;xr=ix+a['inner_width_mm']/2;yb=iy-a['inner_height_mm']/2;yt=iy+a['inner_height_mm']/2
    dr.line([p(xl,yb-5),p(xl,yt+5)],fill='#126b82',width=3);dr.line([p(xl-5,yb),p(xr+5,yb)],fill='#126b82',width=3)
    label(dr,p(xl-16,cy),'A');label(dr,p(cx,yb-10),'B');arrow(dr,p(xl,yt+12),p(xr,yt+12),text='W')
    for name,slot in zip(['SW','NE'],d['inner_slots']):
        x,y=slot['center_mm'];label(dr,p(x-9,y+13),name);arrow(dr,p(xl,y),p(x-slot['width_mm']/2,y))
        arrow(dr,p(x,yb),p(x,y-slot['height_mm']/2))
        for u,v in [(x-slot['width_mm']/2,y),(x+slot['width_mm']/2,y),(x,y-slot['height_mm']/2),(x,y+slot['height_mm']/2)]:
            px,py=p(u,v);dr.ellipse((px-4,py-4,px+4,py+4),fill='#ffe345',outline='#174e61',width=2)
    label(dr,(30,30),'FRONT / amber geometry is provisional');im.save(views/'inner_measure.png')
    c=d['candidate'];gasketz=c['seal_display_thickness_mm']+c['thickness_mm'];innerz=gasketz+a['gasket_free_thickness_mm']
    im,dr=canvas('inner_back');label(dr,(30,30),'BACK / do not compress the foam')
    gw=a.get('gasket_outer_width_mm',a['inner_width_mm']);gh=a.get('gasket_outer_height_mm',a['inner_height_mm']);pr=lambda x,y:projected('inner_back',(x,y,gasketz))
    arrow(dr,pr(ix-gw/2,iy),pr(ix+gw/2,iy));arrow(dr,pr(ix,iy-gh/2),pr(ix,iy+gh/2));label(dr,(300,690),'OW');label(dr,(680,210),'OH')
    contact(dr,pr(ix-gw/2+a['gasket_width_mm'],iy+10),'Inner foam edge',(860,390));contact(dr,pr(ix-gw/2,iy+10),'Outer foam edge',(930,520))
    label(dr,(45,1180),'Map every foam edge, notch and missing segment');im.save(views/'gasket_measure.png')
    im,dr=canvas('section_controls');pr=lambda x,y,z:projected('section_controls',(x,y,z))
    label(dr,(30,30),'M04: R rear metal datum / F formed face / U hub end')
    contact(dr,pr(ix,yt-5,innerz),'R',(350,170));contact(dr,pr(ix,yt-5,innerz+a['inner_formed_depth_mm']),'F',(700,170))
    contact(dr,pr(ix,yt-1,innerz),'T1: rear sheet face',(60,280));contact(dr,pr(ix,yt-1,innerz+a['inner_sheet_thickness_mm']),'T2: front sheet face',(800,280))
    contact(dr,pr(top[0],top[1]+22,innerz+a.get('hub_projection_envelope_mm',a['inner_formed_depth_mm']+3)),'U',(800,440))
    label(dr,(30,1150),'M04-R: inspect the actual back for rear projections.');label(dr,(30,1200),'No hidden rear shape or compression is established.');im.save(views/'depth_measure.png')
    im,dr=canvas('outer_front');r=d['nominal']['trim_diameter_mm']/2;pr=lambda x,y:projected('outer_front',(x,y,gasketz))
    label(dr,(30,30),'M06: FRONT / measure opening edges from rim tangents')
    arrow(dr,pr(cx-r,cy+r+10),pr(cx+r,cy+r+10),text='OD')
    dr.line([pr(cx-r,cy-r),pr(cx-r,cy+r)],fill='#126b82',width=3);dr.line([pr(cx-r,cy-r),pr(cx+r,cy-r)],fill='#126b82',width=3)
    arrow(dr,pr(cx-r,low[1]),pr(low[0]-18,low[1]),text='XN');arrow(dr,pr(low[0],cy-r),pr(low[0],low[1]-18),text='YN')
    contact(dr,pr(low[0]+18,low[1]),'XF: far edge',(890,850));contact(dr,pr(low[0],low[1]+18),'YF: far edge',(870,610))
    label(dr,(30,1190),'Cavity C: REAR rim plane to shell beside each stud.');im.save(views/'trim_measure.png')
    im,dr=canvas('outer_back');label(dr,(30,30),'M06-C / BACK / cavity locations follow both studs')
    for name,point in zip(['SW','NE'],d['studs_mm']):
        p=projected('outer_back',(point[0],point[1],gasketz+a['outer_cavity_depth_mm']));contact(dr,p,name+' cavity',(p[0]+25,p[1]-70))
    label(dr,(30,1190),'Reference the rear rim plane; report both clearances.');im.save(views/'trim_back_measure.png')
    im,dr=canvas('section_studs');pr=lambda p:projected('section_studs',p);label(dr,(30,30),'M07: Z = reference height H minus gap G')
    sw,ne=np.array(d['studs_mm'][0]),np.array(d['studs_mm'][1]);mid=(sw+ne)/2;v=ne-sw;v[2]=0;v/=np.linalg.norm(v);H=max(sw[2],ne[2])+20
    ends=[]
    for t in [-105,105]:
        base=mid+v*t;base[2]=0;cap=base.copy();cap[2]=H;ends.append(cap);arrow(dr,pr(base),pr(cap),text='H')
    dr.line([pr(ends[0]),pr(ends[1])],fill='#126b82',width=5)
    for name,point in [('SW',sw),('NE',ne)]:
        cap=point.copy();cap[2]=H;arrow(dr,pr(point),pr(cap),text='G '+name)
    label(dr,(30,1140),'Blue reference is illustrative: use equal measured blocks.');label(dr,(30,1190),'Rest on intact tile; measure each gap without pushing tips.');im.save(views/'stud_measure.png')
    im,dr=canvas('control_depth');pr=lambda p:projected('control_depth',p)
    label(dr,(30,30),'Check 10: identify the exposed control tips U / L')
    label(dr,(30,80),'H - G = projection from tile; adapter identity is separate')
    H=max(top[2],low[2])+20
    bases=[np.array([0.,-65.,0.]),np.array([0.,155.,0.])]
    caps=[p+np.array([0.,0.,H]) for p in bases]
    dr.line([pr(caps[0]),pr(caps[1])],fill='#126b82',width=5)
    for base,cap in zip(bases,caps):arrow(dr,pr(base),pr(cap),text='H')
    for name,point in [('U',np.array(top)),('L',np.array(low))]:
        cap=point.copy();cap[2]=H;arrow(dr,pr(point),pr(cap),text='G '+name)
        p=pr(point);contact(dr,p,name,(p[0]-155,p[1]-45))
    label(dr,(30,1010),'Observed scan only. Shower side is left.')
    label(dr,(30,1060),'Blue setup is illustrative: intact tile, equal blocks, light contact.')
    im.save(views/'control_depth_measure.png')
    im,dr=canvas('neighbor');checks=json.loads((ROOT/'deliverables/current/analysis/checks.json').read_text())
    gap=next(x for x in checks['checks'] if x['id']=='NEIGHBOR-TRIM-CLEARANCE')
    p,q=[projected('neighbor',(*xy,66)) for xy in gap['gap_endpoints_xy_mm']]
    arrow(dr,p,q);contact(dr,((p[0]+q[0])/2,(p[1]+q[1])/2),f"{gap['candidate_to_diverter_gap_mm']:.1f} mm gap",(850,790))
    label(dr,(35,35),'Neighbor trim / conditional projected clearance')
    label(dr,(35,1160),f"Cyan: {d['candidate']['diameter_mm']:.0f} mm trial. Amber: {d['nominal']['diverter_trim']['diameter_mm']:.1f} mm nominal diverter.")
    label(dr,(35,1210),'Physical scale, centering, handle travel and tool access unresolved.')
    im.save(views/'neighbor_measure.png')

def build():
    d=json.loads((ROOT/'data/derived/resolved.json').read_text());checks=json.loads((ROOT/'deliverables/current/analysis/checks.json').read_text());groups=requests(d);steps=manual_steps();OUT.mkdir(parents=True,exist_ok=True)
    for f in ['style.css','form.js','viewer.js','depth.js']:shutil.copy2(Path(__file__).parent/f,OUT/f)
    shutil.copytree(Path(__file__).parent/'vendor',OUT/'vendor',dirs_exist_ok=True)
    for number in [1,2]:
        src=ROOT/f'data/evidence/scan_quality/plate_scan_{number}.png'
        if src.exists():shutil.copy2(src,OUT/f'views/plate_scan_{number}.png')
    annotations(d)
    depth=json.loads((ROOT/'deliverables/current/analysis/depth_stack.json').read_text())
    for case in depth['cases']:(OUT/f'views/depth_{case}.svg').write_text(depth_svg(depth,case))
    depth_section=depth_html(depth)
    (OUT/'measurement_requests.json').write_text(json.dumps({'project_id':d['project_id'],'revision':d['revision'],'groups':groups},indent=2)+'\n')
    (OUT/'manual_steps.json').write_text(json.dumps(steps,indent=2)+'\n')
    esc=html.escape
    accepted={m['id']:m for m in json.loads((ROOT/'canon/measurements.json').read_text())['measurements'] if m['status']=='user-confirmed'}
    measured_rows=''.join(f"<tr><td>{esc(m.get('purpose',m['id']))}</td><td>{'approximately ' if m.get('approximate') else ''}{m['value_mm']:g} mm</td></tr>" for m in accepted.values() if m.get('raw_readings') and not m['id'].startswith(('M06-','M12-')))
    plate_evidence=f'''<section id="measured-plate"><h2>Your actual inner plate</h2><div class="grid"><figure><a href="views/inner_photo.png"><img src="views/inner_photo.png" alt="User-confirmed front of the actual inner plate with caliper annotations"></a><figcaption>Front, toward handles. Original annotated evidence preserved. The diagonal is between nearest hole edges; 11.71 mm runs from the NE hole edge to the right metal rim.</figcaption></figure><div><table><thead><tr><th>Accepted observation</th><th>Value</th></tr></thead><tbody>{measured_rows}</tbody></table><p>The 6.5-inch height converts to 165.1 mm; the conversion adds no measurement accuracy. Width is 14.35 mm greater than the former 116 mm placeholder. Upper-opening center is 42.23 mm below the top edge by calculation.</p><p>Only the SW mounting-hole diameter is measured. If NE also measures 5.66 mm, diagonal center spacing would be 112.05 mm and its center would lie 14.54 mm from the right rim. Those two results remain conditional.</p><p>The reconstructed metal now uses the measured spans, a rounded rectangular outline and round mounting holes. Corner radii, lower opening, NE diameter, installed registration and local metal depths remain provisional. The separately reported free envelope is 15.44 mm, including approximately 6 mm foam thickness; the band is approximately 6 mm wide. This does not establish compressed depth or nut seating. The rear foam footprint is still an independent assumption; this front photograph cannot verify a sealing landing.</p><p><a href="#check-11">Complete the remaining plate measurements</a>. Use Checks 04, 05 and 10 for the depth and shower-water questions.</p></div></div></section>'''
    pending={k:v for o in d['observations'] for k,v in o.get('pending_contact_readings',{}).items() if k not in accepted}
    outer_rows=''.join(f"<tr><td>{esc(m['purpose'])}</td><td>{m['raw_readings'][0]:g} {esc(m['raw_unit'])}"+(f" = {m['value_mm']:g} mm" if m['raw_unit']!='mm' else '')+f"</td><td>{esc(m['method'])}</td></tr>" for m in accepted.values() if m.get('raw_readings') and m['id'].startswith(('M06-','M12-')))
    pending_rows=''.join(f'<tr><td>{esc(k)}</td><td>{v:g} mm</td><td>Reported; exact contact edges awaiting clarification</td></tr>' for k,v in pending.items())
    plate_evidence+=f'''<section id="measured-cover"><h2>Your actual outer cover</h2><div class="grid"><figure><a href="views/outer_photo.png"><img loading="lazy" src="views/outer_photo.png" alt="Actual outward-facing cover with user measurements: upper bore 33.79 mm, diameter 7.25 inches, gap 46.25 mm and lower rim gap 35.23 mm"></a><figcaption>Front, toward handles. Millimeter readings were taken by caliper; the diameter by tape. Original evidence preserved.</figcaption></figure><div><table><thead><tr><th>Observation</th><th>Reading</th><th>Method / status</th></tr></thead><tbody>{outer_rows}{pending_rows}</tbody></table><p>The measured 184.15 mm outer diameter confirms the existing nominal size. The upper bore now measures 33.79 mm in CAD, replacing its 36 mm placeholder. The lower diameter remains unknown; its display placeholder is still 36 mm.</p><p>The blue gap is not a center-to-center reading. A confirmed inside-edge gap plus half of each opening diameter gives vertical center separation. Do not assume that the lower bore equals the upper one.</p><p>These front-face dimensions do not change the captured valve, control tips, studs or wall. Rear cavity, nut clearance, foam compression and seating remain unresolved. The free 15.44 mm inner-plate envelope cannot be compared with an unmeasured local cover cavity as an installed fit verdict.</p><p><a href="#check-12">Measure the lower opening</a>; use <a href="#check-06">Check 06-C</a> for the cavity beside both studs.</p></div></div></section>'''
    figures=''.join(f'<figure><a href="views/{name}.png"><img loading="lazy" src="views/{name}.png" alt="{esc(title)}"></a><figcaption>{esc(title)}</figcaption></figure>' for name,title in [('coverage','Observed damage and nominal/proposed outlines'),('control_depth_measure','Observed control side view: identify U/L tips before comparing rough-in depth'),('factory','Original-wall trial: cover intersects unchanged hardware'),('assembled','Rejected trial: unchanged studs pass through assumed seated cover'),('neighbor_measure','Separate diverter trim clearance; conditional projected gap'),('exploded','Exploded display; offsets are not installed positions'),('inner_front','Inner plate front: measured spans; remaining shape, depths and placement provisional'),('inner_back','Inner plate back: assumed gasket, not verified landing'),('outer_front','Outer trim front: measured outer diameter and upper bore; lower bore and placement provisional'),('trim_back_measure','Outer trim back: provisional cavity and stud locations'),('gasket','Gasket over observed opening; support unresolved'),('section_controls','Diagnostic section through control line; hidden profiles assumed'),('section_studs','Diagnostic section through studs; interference is not an acceptable fit'),('overview','Full capture including the separate lower diverter')])
    measurement_html=''
    for g in groups:
        fields=''
        for f in g['fields']:
            if f['id'] in pending:
                fields+=f"<p><strong>{esc(f['label'])}:</strong> reported {pending[f['id']]:g} mm; awaiting contact-edge clarification. No repeat reading requested.</p>"
                continue
            if f['id'] in accepted:
                fields+=f"<p><strong>{esc(f['label'])}:</strong> recorded {'approximately ' if accepted[f['id']].get('approximate') else ''}{accepted[f['id']]['value_mm']:g} mm. Return any correction with the measurement ID {f['id']}.</p>"
                continue
            id=f['id'];prediction='Unknown' if f['prediction_mm'] is None else f"Estimate {f['prediction_mm']:.1f} mm"
            fields+=f'''<div class="field" data-measurement="{id}" data-group="{g['id']}"><strong>{id} · {esc(f['label'])}</strong><div class="field-meta">{esc(f['contacts'])}<br>{prediction}; useful accuracy ±{f['useful_accuracy_mm']} mm. Role: {f['role']}.</div><div class="input-grid"><label>Raw reading<input id="{id}-raw" class="raw" inputmode="decimal"></label><label>Units<select id="{id}-units" class="units"><option>mm</option><option>in</option><option>cm</option></select></label><label>Repeat readings, comma separated<input id="{id}-repeat" class="repeat"></label></div><div class="method-line"><label>Tool / method<input id="{id}-method" class="method" value="{esc(f['method'])}"></label><label>Notes / location<input id="{id}-notes" class="notes"></label></div></div>'''
        caption='Actual front-face photo, supplied and annotated by you.' if g['id'] in ('11','12') else 'Observed scan with illustrative tool-contact lines. Tip identity and physical scale remain unverified.' if g['id']=='10' else 'Project render. Amber parts and assumed cavity/gasket details require comparison with the actual part.'
        measurement_html+=f'''<details id="check-{g['id']}" {'open' if g['id'] in ('01','10') else ''}><summary>{g['id']} · {esc(g['title'])} {'<span class="badge">FIRST CHECK</span>' if g['first'] else '<span class="badge">DEPTH FOLLOW-UP</span>' if g['id']=='10' else '<span class="badge">ACTUAL PLATE</span>' if g['id'] in ('11','12') else '<span class="badge">INSTALLER / LATER</span>'}</summary><div class="measurement-layout"><figure><a href="views/{g['view']}.png"><img src="views/{g['view']}.png" loading="lazy" alt="Measurement contact points for check {g['id']}"></a><figcaption>{esc(caption)}</figcaption></figure><div><p><strong>Resolves:</strong> {esc(g['purpose'])}</p><p>{esc(g['instructions'])}</p>{fields}<label>Photo / trace reference and group notes<textarea id="photo-{g['id']}"></textarea></label></div></div></details>'''
    coverage_rows=''.join(f"<tr><td>{r['feature_id']}</td><td>{r['outer_margin_mm']['nominal_trim']:.1f}</td><td>{r['outer_margin_mm']['prior_8in']:.1f}</td><td>{r['outer_margin_mm']['prior_8_25in']:.1f}</td><td>{r['outer_margin_mm']['candidate']:.1f}</td><td>UNRESOLVED</td></tr>" for r in checks['coverage'])
    check_rows=''.join(f"<tr><td>{r['id']}</td><td>{esc(r.get('conditional_result',r.get('criterion','')))}</td><td>{esc(r.get('needed',''))}</td><td><span class='badge unresolved'>{r['status']}</span></td></tr>" for r in checks['checks'])
    manual_html=''.join(f'''<article class="card manual-step"><img src="views/{s['view']}.png" alt="{esc(s['title'])}" loading="lazy"><div><span class="step-number">{i:02d}</span><h3>{esc(s['title'])}</h3><p><strong>Who:</strong> {esc(s['person'])}<br><strong>Before:</strong> {esc(s['prerequisite'])}<br><strong>Tools:</strong> {esc(s['tools'])}</p><p>{esc(s['action'])}</p><p><strong>Check:</strong> {esc(s['check'])}</p><p class="notice"><strong>Stop:</strong> {esc(s['stop'])}</p></div></article>''' for i,s in enumerate(steps,1))
    revision=d['revision'];parts=json.loads((ROOT/'data/derived/cad/parts.json').read_text())['parts']
